TypeScript (sketch):
import { defineTool, callTool } from '@redwood/sdk'

const price = defineTool({
  name: 'price_lookup',
  input: { sku: 'string', qty: 'number' },
  output: { price_cents: 'number' }
})

const res = await callTool('price_lookup', { sku: 'ABC123', qty: '2' }, { idempotencyToken: uid(), strictValidation: false })

// stream helper returns async iterable with resume(token) method
const s = callToolStream('logs_export', { jobId: 'x' }); await s.resume('cursor-9')

